package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.domain.*; import com.bombay.restaurantintelligence.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/transactions") public class TransactionController {private final TransactionQueryService service;public TransactionController(TransactionQueryService service){this.service=service;}@GetMapping public List<TransactionView> recent(){return service.recent();}@GetMapping("/{id}") public TransactionDetail detail(@PathVariable UUID id){return service.detail(id);}
 @Service public static class TransactionQueryService {private final TransactionRepository tx;private final AuditLogRepository audits;TransactionQueryService(TransactionRepository tx,AuditLogRepository audits){this.tx=tx;this.audits=audits;}@Transactional(readOnly=true) public List<TransactionView> recent(){return tx.findTop50ByOrderByCreatedAtDesc().stream().map(TransactionView::of).toList();}@Transactional(readOnly=true) public TransactionDetail detail(UUID id){TransactionEntity t=tx.findById(id).orElseThrow();List<AuditView> a=audits.findByEntityIdOrderByChangedAtDesc(id).stream().map(AuditView::of).toList();return TransactionDetail.of(t,a);}}
 public record TransactionView(UUID id,LocalDate businessDate,String type,String category,String vendor,String employee,BigDecimal amount,String currency,String status,String sourceType,Instant createdAt){static TransactionView of(TransactionEntity t){return new TransactionView(t.getId(),t.getBusinessDate(),t.getTransactionType().name(),t.getCategory()==null?null:t.getCategory().getCode(),t.getVendor()==null?null:t.getVendor().getName(),t.getEmployee()==null?null:t.getEmployee().getName(),t.getAmount(),t.getCurrency(),t.getStatus().name(),t.getSourceType(),t.getCreatedAt());}}
 public record TransactionDetail(UUID id,LocalDate businessDate,String type,String category,String vendor,String employee,BigDecimal amount,String currency,String description,String status,String sourceType,String sourceReference,String sourceMessageId,String sourceFilename,String sender,Instant receivedAt,String rawText,String originalFileLocation,String fileChecksum,BigDecimal extractionConfidence,BigDecimal normalizationConfidence,Instant createdAt,List<AuditView> auditHistory){static TransactionDetail of(TransactionEntity t,List<AuditView>a){return new TransactionDetail(t.getId(),t.getBusinessDate(),t.getTransactionType().name(),t.getCategory()==null?null:t.getCategory().getCode(),t.getVendor()==null?null:t.getVendor().getName(),t.getEmployee()==null?null:t.getEmployee().getName(),t.getAmount(),t.getCurrency(),t.getDescription(),t.getStatus().name(),t.getSourceType(),t.getSourceReference(),t.getSourceMessageId(),t.getSourceFilename(),t.getSender(),t.getReceivedAt(),t.getRawText(),t.getOriginalFileLocation(),t.getFileChecksum(),t.getExtractionConfidence(),t.getNormalizationConfidence(),t.getCreatedAt(),a);}}
 public record AuditView(String oldValue,String newValue,String changedBy,Instant changedAt,String reason){static AuditView of(AuditLog a){return new AuditView(a.getOldValue(),a.getNewValue(),a.getChangedBy(),a.getChangedAt(),a.getReason());}}
}
